package com.ruoyi.framework.audit;
import java.util.*;import java.nio.file.*;import com.alibaba.fastjson2.*;import org.junit.jupiter.api.Test;import org.junit.jupiter.api.io.TempDir;import static org.junit.jupiter.api.Assertions.*;import static org.junit.jupiter.api.Assumptions.*;import static org.mockito.Mockito.*;import static org.mockito.ArgumentMatchers.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.jdbc.datasource.DriverManagerDataSource;import org.springframework.jdbc.datasource.DataSourceTransactionManager;import org.springframework.dao.DataAccessResourceFailureException;import org.springframework.transaction.PlatformTransactionManager;
class AuditFallbackDatabaseLiveTest{
 @Test void outageFallbackReplaysOnceIntoIsolatedTables(@TempDir Path temp)throws Exception{
  String location=System.getProperty("full.fix.root");assumeTrue(location!=null,"显式本地数据库隔离验收");Map<String,String> env=new HashMap<>();for(String line:Files.readAllLines(Path.of(location,".env"))){int i=line.indexOf('=');if(i>0){String v=line.substring(i+1);if(v.startsWith("'")&&v.endsWith("'"))v=v.substring(1,v.length()-1);env.put(line.substring(0,i),v);}}
  var ds=new DriverManagerDataSource();ds.setDriverClassName("com.mysql.cj.jdbc.Driver");ds.setUrl("jdbc:mysql://127.0.0.1:"+env.getOrDefault("MYSQL_PORT","3308")+"/heavy_metal?useUnicode=true&characterEncoding=utf8&serverTimezone=Asia/Shanghai&rewriteBatchedStatements=true");ds.setUsername(env.get("MYSQL_USER"));ds.setPassword(env.get("MYSQL_PASSWORD"));JdbcTemplate actual=new JdbcTemplate(ds);

 String prefix="audit_test_"+UUID.randomUUID().toString().replace("-","")+"_";var made=new ArrayList<String>();var tables=List.of("audit_outbox","sys_oper_log","sys_logininfor","audit_scope","audit_file_cursor","metal_factory");
 try{for(String name:tables){actual.execute("CREATE TABLE "+prefix+name+" LIKE "+name);made.add(prefix+name);}var failed=mock(JdbcTemplate.class);when(failed.queryForList(anyString(),any(Object[].class))).thenThrow(new DataAccessResourceFailureException("simulated connection outage"));var manager=mock(PlatformTransactionManager.class);when(manager.getTransaction(any())).thenThrow(new DataAccessResourceFailureException("independent tx unavailable"));var c=new AuditContext();c.path="/metal/work-order";c.verb="POST";c.actorId=2L;c.actorFactory=7L;c.factories.add(7L);c.request=AuditRequestCapture.bounded(Map.of("body",Map.of("password","temporary-sentinel","reason","outage reason")));var file=temp.resolve(prefix+"fallback.jsonl");
 try(var files=mockStatic(AuditRecorder.class)){files.when(()->AuditRecorder.fallback(anyMap(),eq(file))).thenCallRealMethod();files.when(()->AuditRecorder.fallback(anyMap())).thenAnswer(a->{AuditRecorder.fallback(a.getArgument(0),file);return null;});new AuditRecorder(failed,manager).failure(c,"SYSTEM_ERROR","database unavailable");}
 assertFalse(c.logged);String line=Files.readString(file);assertFalse(line.contains("temporary-sentinel"));assertTrue(JSON.parseObject(line).getBooleanValue("factoryNameUnavailable"));Files.writeString(file,line,StandardOpenOption.APPEND);
 var jdbc=new AuditQueueDatabaseLiveTest.IsolatedJdbc(ds,prefix);var delivery=new AuditDelivery(jdbc,new DataSourceTransactionManager(ds));delivery.replayFallback(file);delivery.replayFallback(file);delivery.deliver();
 assertEquals(1,actual.queryForObject("SELECT COUNT(*) FROM "+prefix+"sys_oper_log WHERE event_id=?",Integer.class,c.event));var row=actual.queryForMap("SELECT result_code,factory_name FROM "+prefix+"sys_oper_log WHERE event_id=?",c.event);assertEquals("SYSTEM_ERROR",row.get("result_code"));assertNull(row.get("factory_name"));assertEquals(1,actual.queryForObject("SELECT COUNT(*) FROM "+prefix+"audit_scope",Integer.class));
 }finally{for(String name:made.reversed()){assertTrue(name.startsWith(prefix));actual.execute("DROP TABLE "+name);}}
 }
}
